def main():
    source = json.loads((CONTENT / "source-index.json").read_text(encoding="utf-8"))
    for module in MODULES:
        for slide in source["coverage"]["moduleToSlides"][module["id"]]:
            module["sources"].append({"id": f"deck-slide-{slide:03d}", "title": f"DOSY in practice GERMN2026 EN v6d · slide {slide}",
                                      "localPath": "source-index.json", "slide": slide})
        module["sources"].append({"id": f"lab-{module['scene']}", "title": f"Diffusion Motion Lab v2 · {module['scene']}",
                                  "url": f"https://diffatonce.com/diffusion-motion-lab/?scene={module['scene']}",
                                  "localPath": "../lab/physics-catalog.json"})
        if module["id"] == "algorithm-selection":
            module["sources"].append({"id": "algorithm-catalog", "title": "Audited bilingual method catalogue: 72 records", "localPath": "algorithm-catalog.json"})
    course = {"version": "1.0.0", "title": B("DiffAtOnce Academy · DOSY en la práctica", "DiffAtOnce Academy · DOSY in practice"),
              "sourceSha256": source["input"]["sha256"], "reviewedDate": "2026-10-05",
              "evidencePolicy": B("Formación con simulaciones ideales, esquemas y ejemplos históricos atribuidos. No opera el espectrómetro ni valida calibraciones o identidades.",
                                  "Training with ideal simulations, diagrams and attributed historical examples. Does not operate the spectrometer or validate calibrations or identities."),
              "modules": MODULES}
    assert len(MODULES) == 24
    (CONTENT / "course.json").write_text(json.dumps(course, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"Wrote {len(MODULES)} modules, {sum(len(m['questions']) for m in MODULES)} graded questions, "
          f"{sum(len(m['examples']) for m in MODULES)} examples; 81/81 source slides mapped.")

if __name__ == "__main__": main()
